gajS(){return"\u2022 TP.HCM: th\u1eddi gian ch\u1ea1y to\xe0n tuy\u1ebfn theo bi\u1ec3u \u0111\u1ed3 c\u1ee7a ngu\u1ed3n, chia cho t\u1eebng tr\u1ea1m theo qu\xe3ng \u0111\u01b0\u1eddng d\u1ecdc l\u1ed9 tr\xecnh.\n\u2022 H\xe0 N\u1ed9i: ngu\u1ed3n kh\xf4ng cho th\u1eddi gian ch\u1ea1y \u2192 \u01b0\u1edbc theo chi\u1ec1u d\xe0i l\u1ed9 tr\xecnh v\u1edbi v\u1eadn t\u1ed1c trung b\xecnh 16 km/h (bu\xfdt, \u0111\xe3 t\xednh d\u1eebng \u0111\xf3n tr\u1ea3 kh\xe1ch) v\xe0 35 km/h (metro).\n\u2022 Kh\xf4ng t\xednh k\u1eb9t xe th\u1ef1c t\u1ebf \u2014 gi\u1edd cao \u0111i\u1ec3m c\xf3 th\u1ec3 ch\u1eadm h\u01a1n."},
gajX(){return"\u0110i b\u1ed9 v\xe0 chuy\u1ec3n tuy\u1ebfn"},
gajW(){return'\u2022 T\u1ed1c \u0111\u1ed9 \u0111i b\u1ed9 1,2 m/s (~4,3 km/h, \u0111\xe3 t\xednh ch\u1edd \u0111\xe8n). Qu\xe3ng \u0111\u01b0\u1eddng \u0111i b\u1ed9 = \u0111\u01b0\u1eddng chim bay \xd7 1,3 (\u0111\u01b0\u1eddng ph\u1ed1 quanh co).\n\u2022 \u0110i b\u1ed9 t\u1edbi tr\u1ea1m t\u1ed1i \u0111a 800 m; chuy\u1ec3n tuy\u1ebfn \u0111i b\u1ed9 t\u1ed1i \u0111a 400 m v\xe0 c\u1ea7n \xedt nh\u1ea5t 1 ph\xfat; t\u1ed1i \u0111a 4 ch\u1eb7ng xe.\n\u2022 N\u1ebfu b\u1ea1n b\u1eadt "\u0110\u01b0\u1eddng \u0111i theo ph\u1ed1", \u0111o\u1ea1n \u0111i b\u1ed9 \u0111\u01b0\u1ee3c v\u1ebd theo \u0111\u01b0\u1eddng th\u1eadt (OSRM/FOSSGIS, d\u1eef li\u1ec7u OpenStreetMap); th\u1eddi gian v\u1eabn t\xednh nh\u01b0 tr\xean.'},
gajP(){return"X\u1ebfp h\u1ea1ng ph\u01b0\u01a1ng \xe1n"},
gajO(){return'\u2022 "\u0110\u1ec1 xu\u1ea5t": gi\u1edd t\u1edbi s\u1edbm nh\u1ea5t, m\u1ed7i l\u1ea7n chuy\u1ec3n tuy\u1ebfn t\xednh th\xeam 5 ph\xfat (v\xec chuy\u1ec3n tuy\u1ebfn m\u1ec7t v\xe0 d\u1ec5 l\u1ee1 xe). Tuy\u1ebfn gi\xe1 cao (li\xean t\u1ec9nh, s\xe2n bay \u2013 V\u0169ng T\xe0u, bu\xfdt du l\u1ecbch) ch\u1ec9 \u0111\u01b0\u1ee3c \u0111\u1ec1 xu\u1ea5t khi nhanh h\u01a1n h\u1eb3n: m\u1ed7i ngh\xecn \u0111\u1ed3ng v\u01b0\u1ee3t 20.000\u0111 t\xednh nh\u01b0 ch\u1eadm th\xeam 1 ph\xfat.\n\u2022 C\xe1c ti\xeau ch\xed kh\xe1c (nhanh nh\u1ea5t, \xedt chuy\u1ec3n, r\u1ebb nh\u1ea5t, ng\u1eafn nh\u1ea5t, \xedt \u0111i b\u1ed9) \u2014 ho\xe0 th\xec x\xe9t gi\u1edd t\u1edbi.\n\u2022 Nhi\u1ec1u \u0111i\u1ec3m d\u1eebng: m\u1ed7i \u0111o\u1ea1n ch\u1ecdn ph\u01b0\u01a1ng \xe1n t\u1ed1t nh\u1ea5t theo ti\xeau ch\xed \u0111ang ch\u1ecdn; "T\u1ed1i \u01b0u th\u1ee9 t\u1ef1" th\u1eed m\u1ecdi th\u1ee9 t\u1ef1 gh\xe9 v\xe0 ch\u1ecdn th\u1ee9 t\u1ef1 t\u1edbi n\u01a1i s\u1edbm nh\u1ea5t.'},
gajL(){return"Gi\xe1 v\xe9"},
gajK(){return'\u2022 Gi\xe1 v\xe9 l\u01b0\u1ee3t c\u1ee7a t\u1eebng tuy\u1ebfn theo ngu\u1ed3n c\xf4ng b\u1ed1; t\u1ed5ng = c\u1ed9ng gi\xe1 c\xe1c ch\u1eb7ng (kh\xf4ng t\xednh v\xe9 th\xe1ng, mi\u1ec5n gi\u1ea3m hay v\xe9 li\xean th\xf4ng).\n\u2022 Tuy\u1ebfn ch\u01b0a c\xf3 gi\xe1 trong ngu\u1ed3n \u2192 hi\u1ec7n "gi\xe1 v\xe9 ch\u01b0a r\xf5" thay v\xec \u0111o\xe1n.'},
gajH(){return"Khi h\u1ebft xe: \u0111i b\u1ed9, xe m\xe1y / taxi"},
gajG(){return'\u2022 \u0110\u01b0\u1eddng \u0111i b\u1ed9 v\xe0 \u0111\u01b0\u1eddng xe l\u1ea5y t\u1eeb OSRM (FOSSGIS, d\u1eef li\u1ec7u OpenStreetMap), ch\u1ec9 khi b\u1ea1n \u0111\xe3 cho ph\xe9p.\n\u2022 Th\u1eddi gian xe m\xe1y / taxi = l\u1ea5y m\u1ee9c ch\u1eadm h\u01a1n gi\u1eefa (th\u1eddi gian OSRM \xd7 1,3) v\xe0 (qu\xe3ng \u0111\u01b0\u1eddng \u1edf 25 km/h) \u2014 v\xec OSRM kh\xf4ng bi\u1ebft k\u1eb9t xe. Ch\u1ec9 l\xe0 \u01b0\u1edbc t\xednh.\n\u2022 "Chuy\u1ebfn s\u1edbm nh\u1ea5t" = ch\u1ea1y l\u1ea1i t\xecm \u0111\u01b0\u1eddng t\u1eeb 4:30 s\xe1ng h\xf4m sau.\n\u2022 "G\u1ea7n chuy\u1ebfn cu\u1ed1i" = l\xean xe trong v\xf2ng 30 ph\xfat tr\u01b0\u1edbc chuy\u1ebfn cu\u1ed1i theo gi\u1edd ho\u1ea1t \u0111\u1ed9ng c\xf4ng b\u1ed1.'},
gajR(){return"H\xe0nh tr\xecnh c\u1ee7a t\xf4i"},
gajQ(){return"\u2022 Km \u0111i xe = qu\xe3ng \u0111\u01b0\u1eddng d\u1ecdc l\u1ed9 tr\xecnh c\xe1c ch\u1eb7ng xe; km \u0111i b\u1ed9 theo c\xe1ch t\xednh \u0111i b\u1ed9 \u1edf tr\xean.\n\u2022 S\u1ed1 b\u01b0\u1edbc \u2248 1.300 b\u01b0\u1edbc/km \u0111i b\u1ed9.\n\u2022 CO\u2082 gi\u1ea3m \u2248 50 g cho m\u1ed7i km \u0111i xe c\xf4ng c\u1ed9ng thay cho xe m\xe1y (xe m\xe1y ~90 g/km, bu\xfdt/metro ~40 g/km m\u1ed7i h\xe0nh kh\xe1ch).\n\u2022 Chuy\u1ebfn quen: \xedt nh\u1ea5t 3 l\u1ea7n c\xf9ng \u0111i\u1ec3m \u0111i\u2013\u0111\u1ebfn, c\xf9ng khung gi\u1edd (\xb190 ph\xfat) trong 6 tu\u1ea7n g\u1ea7n \u0111\xe2y."},
gajJ(){return"\u0110\u1ed9 m\u1edbi c\u1ee7a d\u1eef li\u1ec7u"},
gajI(){return'\u2022 D\u1eef li\u1ec7u tuy\u1ebfn \u0111\u01b0\u1ee3c ki\u1ec3m tra v\xe0 c\u1eadp nh\u1eadt \u0111\u1ecbnh k\u1ef3; ng\xe0y c\u1eadp nh\u1eadt lu\xf4n hi\u1ec7n trong app. Qu\xe1 30 ng\xe0y ch\u01b0a c\u1eadp nh\u1eadt, app s\u1ebd c\u1ea3nh b\xe1o.\n\u2022 \u0110\u1ecba \u0111i\u1ec3m, t\xean \u0111\u01b0\u1eddng, ph\u01b0\u1eddng/x\xe3 (theo \u0111\u1ecba gi\u1edbi t\u1eeb 1/7/2025) l\u1ea5y t\u1eeb OpenStreetMap.\n\u2022 Th\u1ea5y sai? \u0110\xe1nh gi\xe1 \ud83d\udc4e v\xe0 ch\u1ecdn "Gi\u1edd ch\u1ea1y trong app sai" / "Tr\u1ea1m kh\xf4ng c\xf3" / "Tuy\u1ebfn \u0111\xe3 \u0111\u1ed5i l\u1ed9 tr\xecnh" \u2014 b\xe1o c\xe1o \u1ea9n danh \u0111\u01b0\u1ee3c t\u1ed5ng h\u1ee3p m\u1ed7i l\u1ea7n c\u1eadp nh\u1eadt.'},
